attribute vec3 aO, aE; attribute float aT; attribute vec2 aA; uniform float uTime; varying vec3 vN, vV;
    vec3 path(float s){ return mix(aO, aE, s) + vec3(0., 4.*aA.x*s*(1. - s), 0.); }             // arced flight (aA.x = apex height)
    void main(){
      float u = uTime - aT - 0.10, L = length(aE - aO), tt = L/30.0;
      if (u < 0. || u > tt){ gl_Position = vec4(2.,2.,2.,1.); return; }
      float s = u/tt;
      vec3 d = normalize(aE - aO + vec3(0., 4.*aA.x*(1. - 2.*s), 0.)), up = vec3(0., 1., 0.), sd = normalize(cross(d, up)), vu = cross(sd, d);
      float a = 0.;;                                       // flies point first along the arc, a slow roll about its axis
      vec3 b1 = sd*cos(a) + vu*sin(a), b2 = cross(d, b1);
      vec3 q = position*aA.y;                                // aA.y = scale (the single piercing shot is bigger)
      vec3 P = path(s) + d*.05 + d*q.x + b2*q.y + b1*q.z;
      vN = normalize(d*normal.x + b2*normal.y + b1*normal.z); vV = normalize(cameraPosition - P);
      gl_Position = projectionMatrix*viewMatrix*vec4(P, 1.);
    }

